typedef struct N {
    int k;
    struct N *n;
} N; // Chained Node

N* H_BUCKETS[100]; // Hash Table Array

// Insert/Delete using pointer-to-pointer (modifies head or link directly)
void insert_node(N** link, int key) {
    N** curr = link;
    while (*curr) {
        if ((*curr)->k == key) return;
        curr = &(*curr)->n; // Advance pointer to the 'next' pointer
    }
    // *curr is the location (bucket head or N->next) to be updated
    N* new_n = (N*)malloc(sizeof(N));
    if (!new_n) return;
    new_n->k = key;
    new_n->n = NULL;
    *curr = new_n; // Update the link pointed to by curr
}
